  FT["PH-H5604"] = {"id":"PH-H5604","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1991/ra_7116_1991.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Jetafe市","en":"An Act Establishing a High School in Barangay Campao Oriental, Municipality of Jetafe, Province of Bohol, to Be Known as the Campao Oriental High School, and Appropriating Funds Therefor","orig":"An Act Establishing a High School in Barangay Campao Oriental, Municipality of Jetafe, Province of Bohol, to Be Known as the Campao Oriental High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 7116","issuingBody":"Congress of the Philippines","promulgatedDate":"1991-08-22","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1991/ra_7116_1991.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5604-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a high school in Barangay Campao Oriental, Municipality of Jetafe, Province of Bohol to be known as the Campao Oriental High School."}},{"id":"PH-H5604-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H5604-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act is hereby authorized to be appropriated in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5604-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p79"};
  FT["PH-H5605"] = {"id":"PH-H5605","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1991/ra_7117_1991.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Tabuk市","en":"An Act Establishing a High School in Barangay Agbannawag, Municipality of Tabuk, Province of Kalinga-apayao, to Be Known as the Agbannawag High School, and Appropriating Funds Therefor","orig":"An Act Establishing a High School in Barangay Agbannawag, Municipality of Tabuk, Province of Kalinga-apayao, to Be Known as the Agbannawag High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 7117","issuingBody":"Congress of the Philippines","promulgatedDate":"1991-08-22","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1991/ra_7117_1991.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5605-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a high school in Barangay Agbannawag, Municipality of Tabuk, Province of Kalinga-Apayao, to be known as the Agbannawag High School."}},{"id":"PH-H5605-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H5605-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act is hereby authorized to be appropriated in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5605-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p79"};
